// Breadth-first search: spread out from the start one step at a time, like a flood.
// The first time the flood reaches the exit, that's the shortest walk.
const map = nb.get('dungeon') ?? [];
if (map.length === 0) return '<p>Run the Lua cell above first to make a dungeon.</p>';

let start = null;
let coinsTotal = 0;
map.forEach((row, y) => [...row].forEach((ch, x) => {
  if (ch === '@') start = { x, y };
  if (ch === '$') coinsTotal++;
}));
if (!start) return '<p>The map has no start square "@".</p>';

const distance = map.map((row) => Array(row.length).fill(-1));
distance[start.y][start.x] = 0;
const queue = [start];
let steps = null;
let coinsReachable = 0;

for (let i = 0; i < queue.length; i++) {
  const { x, y } = queue[i];
  if (map[y][x] === 'E' && steps === null) steps = distance[y][x];
  if (map[y][x] === '$') coinsReachable++;
  for (const [dx, dy] of [[0, -1], [0, 1], [-1, 0], [1, 0]]) {
    const nx = x + dx, ny = y + dy;
    const tile = map[ny]?.[nx];
    if (tile && tile !== '#' && distance[ny][nx] === -1) {
      distance[ny][nx] = distance[y][x] + 1;
      queue.push({ x: nx, y: ny });
    }
  }
}

nb.set('route', { steps, coinsReachable, coinsTotal });

const allCoins = coinsReachable === coinsTotal;
const stat = (label, value) => `<div style="flex:1;background:#1e293b;border-radius:10px;padding:10px 14px">
  <div style="color:#94a3b8;font-size:12px">${label}</div>
  <div style="font-size:24px;font-weight:700;color:#f8fafc">${value}</div></div>`;

return `
<div style="background:#0f172a;color:#e2e8f0;font:14px/1.5 system-ui,sans-serif;border-radius:12px;padding:16px 18px">
  <div style="font-weight:700;font-size:16px;margin-bottom:10px">Route check</div>
  <div style="display:flex;gap:10px">
    ${stat('Steps to the exit', steps === null ? 'no way out!' : steps)}
    ${stat('Coins you can reach', `${coinsReachable} / ${coinsTotal}`)}
  </div>
  <div style="margin-top:12px;font-weight:600;color:${allCoins ? '#4ade80' : '#f87171'}">
    ${allCoins ? '✔ Every coin can be reached' : '✘ Some coins are walled off'}
  </div>
</div>`;
